# Questão
Considere o programa para Arduino listado abaixo. O programa é usado para medir a distância de objetos à frente de um robô usando um sensor de ultrassom através do envio de uma onda sonora que vem com velocidade de 340 m/s. Si o sinal sonoro reflete no objeto à frente do robô, e volta para o sensor de ultrassom. Leve em consideração que a função pulseIn() mede o tempo em microsegundos para que um sinal seja detectado em uma entrada digital do Arduino.

```cpp
int pingPin = 7;

void setup()
{
    Serial.begin(9600);
}

void loop()
{
    long duration, cm;

    pinMode(pingPin, OUTPUT);
    digitalWrite(pingPin, LOW);
    delayMicroseconds(2);
    digitalWrite(pingPin, HIGH);
    delayMicroseconds(5);
    digitalWrite(pingPin, LOW);

    pinMode(pingPin, INPUT);
    duration = pulseIn(pingPin, HIGH);

    cm = microsecondsToCentimeters(duration);

    Serial.print(cm);
    Serial.print("cm");
    Serial.println();

    delay(100);
}

long microsecondsToCentimeters(long microseconds)
{
    return microseconds / 29 / 2;
}

# Questão
Considere o programa para Arduino listado abaixo. O programa é usado para medir a distância de objetos à frente de um robô usando um sensor de ultrassom através do envio de uma onda sonora que vem com velocidade de 340 m/s. Si o sinal sonoro reflete no objeto à frente do robô, e volta para o sensor de ultrassom. Leve em consideração que a função pulseIn() mede o tempo em microsegundos para que um sinal seja detectado em uma entrada digital do Arduino.

```cpp
int pingPin = 7;

void setup()
{
    Serial.begin(9600);
}

void loop()
{
    long duration, cm;

    pinMode(pingPin, OUTPUT);
    digitalWrite(pingPin, LOW);
    delayMicroseconds(2);
    digitalWrite(pingPin, HIGH);
    delayMicroseconds(5);
    digitalWrite(pingPin, LOW);

    pinMode(pingPin, INPUT);
    duration = pulseIn(pingPin, HIGH);

    cm = microsecondsToCentimeters(duration);

    Serial.print(cm);
    Serial.print("cm");
    Serial.println();

    delay(100);
}

long microsecondsToCentimeters(long microseconds)
{
    return microseconds / 29 / 2;
}

